import {dimensionInfographicCard,dimensionGraphic} from './dimension-infographics.mjs?v=explorer-2';
import {workbookDimensions,questionnaireLocale,frequencyCounts} from './innerly-v1-model.mjs?v=mh-14';
import {displayLanguage,languageName} from './mental-language.mjs?v=mh-14';
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const say=(l,en,hi)=>l==='hi'?hi:en;
export const FREE_DIMENSIONS=['dimension-1','dimension-5'];

// These are decorative previews, not hidden paid results. Real entitlement
// enforcement and report generation must move to a backend before charging.
function lockedIllustration(id,l){
 const example=Array.from({length:36},(_,i)=>(i*3+1)%5);
 return `<div class="wb-blurred-art" aria-hidden="true">${dimensionGraphic(example,id,l,true)}<div></div><div></div></div>`;
}

export function workbookReportPreview(report,l='en'){
 l=displayLanguage(l);const stats=frequencyCounts(report.answers),names=questionnaireLocale(l).dimensions;
 const locked=workbookDimensions.filter(d=>!FREE_DIMENSIONS.includes(d.id));
 return `<section class="mh-report wb-report-preview"><header class="wb-preview-heading"><span class="wb-eyebrow">${say(l,'A MOMENT FOR YOUR MIND','कुछ पल, अपने मन के लिए')}</span><h1>${say(l,'Your reflection.<br><em>A little more revealed.</em>','आपकी reflection।<br><em>खुद की थोड़ी और पहचान।</em>')}</h1><p>${say(l,'Start with these two areas. There’s more to explore in your full report.','इन दो पहलुओं से शुरुआत करें। पूरी report में और भी बहुत कुछ समझें।')}</p><div class="wb-preview-meta"><span>${stats.answered} / 36 ${say(l,'answered','जवाब')}</span><span>6 ${say(l,'dimensions','पहलू')}</span><span>${say(l,'Question language','सवालों की भाषा')}: <bdi>${esc(languageName(report.language))}</bdi></span></div></header>
 <div class="wb-free-grid">${FREE_DIMENSIONS.map(id=>dimensionInfographicCard(report.answers,id,l,{preview:true})).join('')}</div><p class="wb-preview-note">${say(l,'Each mark shows an answer you selected. More frequent does not always mean better or worse; each statement has its own meaning.','हर निशान आपका चुना जवाब दिखाता है। ज़्यादा frequency हमेशा बेहतर या खराब नहीं होती; हर सवाल का अपना अर्थ है।')}</p>
 <div class="wb-more-heading"><span class="wb-eyebrow">${say(l,'THERE’S MORE TO YOUR STORY','आपकी कहानी में और भी बहुत कुछ है')}</span><h2>${say(l,'See how the pieces come together.','सभी पहलुओं को साथ समझें।')}</h2></div><div class="wb-lock-field"><div class="wb-locked-grid">${locked.map((d,i)=>`<article class="wb-locked-card"><h3>${esc(names[d.index])}</h3>${lockedIllustration(d.id,l)}</article>`).join('')}</div><div class="wb-unlock-panel"><span class="wb-lock-symbol" aria-hidden="true"><svg viewBox="0 0 32 32" width="28" height="28"><rect x="7" y="14" width="18" height="14" rx="4" fill="none" stroke="currentColor" stroke-width="2"/><path d="M11 14V9a5 5 0 0110 0v5" fill="none" stroke="currentColor" stroke-width="2"/><circle cx="16" cy="21" r="2" fill="currentColor"/></svg></span><h2>${say(l,'Your full picture is waiting.','आपकी पूरी तस्वीर तैयार है।')}</h2><p>${say(l,'Every dimension. Every answer. A reflection to take with you.','हर पहलू। हर जवाब। सोचने के लिए आपके अपने सवाल।')}</p><ul><li>${say(l,'Explore all 6 dimensions','सभी 6 पहलुओं को समझें')}</li><li>${say(l,'Look closer at every answer','हर जवाब को करीब से देखें')}</li><li>${say(l,'Compare your saved check-ins','अपने सेव check-ins की तुलना करें')}</li><li>${say(l,'Download your full report as a PDF','पूरी report PDF में डाउनलोड करें')}</li></ul><div class="wb-report-price"><strong>$1</strong><span>${say(l,'One-time payment for this report','इस report के लिए एक बार भुगतान')}</span></div><button class="mh-primary" data-action="report-offer">${say(l,'Get my full report','मेरी पूरी report पाएँ')} <span aria-hidden="true">→</span></button><small>${say(l,'Payments coming soon. Free preview available below.','भुगतान जल्द शुरू होंगे। नीचे मुफ़्त preview उपलब्ध है।')}</small></div></div><p class="wb-placeholder-note">${say(l,'Blurred illustrations show the report format, not additional results.','धुंधले चित्र report का स्वरूप दिखाते हैं, अतिरिक्त नतीजे नहीं।')}</p>
 <div class="wb-skip-preview"><button class="mh-link" data-action="unlock-preview">${say(l,'Skip for now — view full report','अभी छोड़ें — पूरी report देखें')} <span aria-hidden="true">→</span></button><p>${say(l,'Free during this preview. No payment details needed.','इस preview में मुफ़्त। भुगतान की जानकारी की ज़रूरत नहीं।')}</p></div><p class="mh-footnote">${say(l,'A self-reflection questionnaire, not a diagnosis. Your responses are not compared with other people.','खुद को समझने के सवाल, diagnosis नहीं। आपकी दूसरों से तुलना नहीं होती।')}</p><div id="mh-report-status" class="mh-form-message" role="status"></div></section>`;
}
